G = (0.02, 0.04, 0.06, 0.08, 0.10, 0.12, 0.15, 0.18, 0.22, 0.26, 0.30, 0.35, 0.40, 0.45, 0.50, 0.60, 0.70, 0.80, 0.90, 1.0)
PTS = (10, 7, 5, 4, 3, 2, 1, 0)
STRT = []
for _m in range(8192):
    _h = -1
    for _hi in range(12, 3, -1):
        _w = 0x1F << (_hi - 4)
        if _m & _w == _w:
            _h = _hi
            break
    if _h < 0 and _m & 0x100F == 0x100F:
        _h = 3
    STRT.append(_h)
STRT = tuple(STRT)
POPC = tuple(bin(_m).count('1') for _m in range(8192))


def pf_index(c1, c2):
    r1, r2 = c1 >> 2, c2 >> 2
    if r1 < r2:
        r1, r2 = r2, r1
    if r1 == r2:
        return r1
    t = r1 * (r1 - 1) // 2 + r2
    return 13 + t if (c1 & 3) == (c2 & 3) else 91 + t


def gidx(x):
    # returns (index, frac) for interpolation on G
    if x <= G[0]:
        return 0, 0.0
    if x >= 1.0:
        return 18, 1.0
    lo = 0
    while G[lo + 1] < x:
        lo += 1
    return lo, (x - G[lo]) / (G[lo + 1] - G[lo])


def eqr(h, w):
    """equity of preflop class h vs top-w range (heads-up)."""
    i, f = gidx(w)
    row = EQR[h]
    return row[i] + (row[i + 1] - row[i]) * f


# call-width table: width of hands with eqr(h, J) >= q, for J in G and q grid
QG = tuple(0.26 + 0.02 * k for k in range(24))   # 0.26..0.72
_CW = []
for _j in range(20):
    _eqs = [(EQR[_h][_j], 6 if _h < 13 else (4 if _h < 91 else 12)) for _h in range(169)]
    _row = []
    for _q in QG:
        _row.append(sum(c for e, c in _eqs if e >= _q) / 1326.0)
    _CW.append(tuple(_row))
CW = tuple(_CW)


def call_width(J, q):
    i, f = gidx(J)
    if q <= QG[0]:
        k, g = 0, 0.0
    elif q >= QG[-1]:
        k, g = 22, 1.0
    else:
        k = int((q - QG[0]) / 0.02)
        if k > 22:
            k = 22
        g = (q - QG[k]) / 0.02
    a = CW[i][k] + (CW[i][k + 1] - CW[i][k]) * g
    b = CW[i + 1][k] + (CW[i + 1][k + 1] - CW[i + 1][k]) * g
    return a + (b - a) * f


def icm(s, n, tot):
    """ICM points value of stack s with n players alive (others equal), total chips tot."""
    if s <= 0:
        return PTS[n - 1] if n >= 1 else 0
    if n <= 1:
        return PTS[0]
    b = (tot - s) / (n - 1.0)
    if b <= 0:
        return PTS[0]
    val = 0.0
    alive = 1.0
    k = n
    for place in range(n - 1):
        p = s / (s + (k - 1) * b)
        val += alive * p * PTS[place]
        alive *= 1.0 - p
        k -= 1
    val += alive * PTS[n - 1]
    return val


def classify(hole, board):
    h0, h1 = hole
    r1, r2 = h0 >> 2, h1 >> 2
    if r1 < r2:
        r1, r2 = r2, r1
    bc = [0] * 13
    bsc = [0, 0, 0, 0]
    bmask = 0
    for c in board:
        r = c >> 2
        bc[r] += 1
        bsc[c & 3] += 1
        bmask |= 1 << r
    sc = bsc[:]
    sc[h0 & 3] += 1
    sc[h1 & 3] += 1
    amask = bmask | (1 << r1) | (1 << r2)
    nb = len(board)
    top = bmask.bit_length() - 1
    mbs = max(bsc)
    tf = 0 if mbs <= 1 else (1 if mbs == 2 else 2)
    paired = 0
    for r in range(13):
        if bc[r] >= 2:
            paired = 1
            break
    sty = 0
    ext = (bmask << 1) | (1 if bmask >> 12 & 1 else 0)
    for lo in range(0, 10):
        if POPC[(ext >> lo) & 0x1F] >= 3:
            sty = 1
            break
    made = -1
    fsuit = -1
    for s in range(4):
        if sc[s] >= 5:
            fsuit = s
    pocket = r1 == r2
    if pocket:
        if bc[r1] >= 2:
            made = 19
        elif bc[r1] == 1:
            made = 19 if paired else 15
    else:
        if bc[r1] >= 1 and bc[r2] >= 1 and paired:
            if bc[r1] >= 2 or bc[r2] >= 2:
                made = 19
        if made < 0 and (bc[r1] >= 2 or bc[r2] >= 2):
            tr = r1 if bc[r1] >= 2 else r2
            other_pair = False
            for r in range(13):
                if bc[r] >= 2 and r != tr:
                    other_pair = True
            if bc[r1] >= 3 or bc[r2] >= 3:
                made = 19
            elif (bc[r1] >= 2 and bc[r2] >= 1) or (bc[r2] >= 2 and bc[r1] >= 1) or other_pair:
                made = 19
            else:
                made = 14
    if fsuit >= 0 and made < 19:
        fm = 0
        for c in board:
            if c & 3 == fsuit:
                fm |= 1 << (c >> 2)
        hm = 0
        if h0 & 3 == fsuit:
            hm |= 1 << (h0 >> 2)
        if h1 & 3 == fsuit:
            hm |= 1 << (h1 >> 2)
        if hm:
            full = fm | hm
            if (STRT[full] >= 0 and STRT[full] != STRT[fm]) if POPC[fm] >= 5 else STRT[full] >= 0:
                made = 19
            else:
                hb = hm.bit_length() - 1
                if POPC[fm] >= 5:
                    ranks = [r for r in range(12, -1, -1) if fm >> r & 1]
                    if hb <= ranks[4]:
                        hb = -1
                if hb >= 0:
                    higher = 0
                    for r in range(hb + 1, 13):
                        if not (full >> r & 1):
                            higher += 1
                    made = 18 if higher == 0 else (17 if higher <= 2 else 16)
    if made < 0:
        sh = STRT[amask]
        if sh >= 0 and sh > STRT[bmask]:
            made = 13
    if made < 0:
        if pocket:
            if r1 > top:
                made = 9
            else:
                above = 0
                for r in range(r1 + 1, 13):
                    if bc[r]:
                        above += 1
                made = 5 if above == 1 else 4
        else:
            p1 = bc[r1] >= 1
            p2 = bc[r2] >= 1
            if p1 and p2:
                made = 12 if r1 == top else 11
            elif p1 or p2:
                pr = r1 if p1 else r2
                kick = r2 if p1 else r1
                if paired:
                    made = 10 if pr == top else 6
                elif pr == top:
                    made = 8 if kick >= 10 else 7
                else:
                    higher = 0
                    for r in range(pr + 1, 13):
                        if bc[r]:
                            higher += 1
                    made = 6 if higher == 1 else 3
            else:
                made = (1 if r1 > top else 0) + (1 if r2 > top else 0)
    draw = 0
    if nb < 5 and made < 16:
        fd = 0
        for s in range(4):
            if sc[s] == 4 and bsc[s] < 4 and ((h0 & 3) == s or (h1 & 3) == s):
                fd = 1
        outs = 0
        if STRT[amask] < 0:
            for r in range(13):
                if not (amask >> r & 1):
                    if STRT[amask | (1 << r)] >= 0 and STRT[bmask | (1 << r)] < 0:
                        outs += 1
        sd = 2 if outs >= 2 else outs
        if fd:
            draw = 4 if sd else 3
        else:
            draw = sd
    return ((nb - 2) * 100 + made) * 100 + draw * 12 + tf * 4 + paired * 2 + sty, made, draw


def ent(e):
    """normalise a history entry to (seat, kind, amount); tolerant of shapes."""
    try:
        if len(e) == 2:
            s, a = e
            if isinstance(a, str):
                return s, a, 0
            kind = a[0]
            amt = a[1] if len(a) > 1 else 0
        else:
            s, kind = e[0], e[1]
            amt = e[2] if len(e) > 2 else 0
        if not isinstance(amt, (int, float)):
            amt = 0
        return s, kind, int(amt)
    except Exception:
        return -1, '', 0


def post_eq(key):
    v = POST.get(key)
    if v is None:
        v = POST.get(key - (key % 100) + (key % 100) // 12 * 12 + 10000000)
        if v is None:
            v = POST.get(key - (key % 100) + 20000000)
            if v is None:
                v = (0.5, 0.35, 0.25, 0.15)
    return v


COLF = ((1.0, 0.50, 0.305, 0.13), (1.0, 0.50, 0.305, 0.13), (1.0, 0.50, 0.326, 0.183), (1.0, 0.573, 0.395, 0.241))


def range_eq(st, f, e0, e1, e2, e3):
    """equity vs the top-f fraction (by board strength) of random hands, interpolating table columns."""
    F = COLF[st]
    if f >= 1.0:
        return e0
    if f >= F[1]:
        t = (f - F[1]) / (1.0 - F[1])
        return e1 + (e0 - e1) * t
    if f >= F[2]:
        t = (f - F[2]) / (F[1] - F[2])
        return e2 + (e1 - e2) * t
    if f >= F[3]:
        t = (f - F[3]) / (F[2] - F[3])
        return e3 + (e2 - e3) * t
    return e3


class Bot(Agent):
    ERRS = 0
    LAST_ERR = None
    # tunables (versioned for self-play tests)
    P = dict(open_scale=1.0, pf_margin=0.0, bluff=1.0, vbet=0.55, call_margin=0.02, jam_bb=15,
             adapt=1.0, icm_on=1.0, raise_th=0.72, c3bet=1.0, shove_mult=1.5, icm_post=0.0, fr=0.0, slow=0.0, bsize=0.0, pc=0.0, cq=0.03, cicm=0.0, jam_bias=0.0, pend=1.0, pos_r=0.0, hu_open=0.85, tb3=0.0, hu_iso=0.0, jg=0.0)

    def __init__(self, **kw):
        self.p = dict(self.P)
        self.p.update(kw)
        self.rng = random.Random()
        self.new_table({}, 0, 8)

    def new_table(self, rules, seat, n_players):
        n = n_players if isinstance(n_players, int) and n_players > 0 else 8
        if n < 2:
            n = 8
        self.n = n
        self.seat = seat
        self.hand = -1
        self.hk = 0
        self.npf = [0] * 16     # observed preflop first actions
        self.vpip = [0] * 16
        self.pfr = [0] * 16
        self.shv = [0] * 16
        self.pagg = [0] * 16    # postflop bets/raises
        self.pact = [0] * 16    # postflop actions
        self.ftb_n = [0] * 16   # faced our preflop aggression
        self.ftb_f = [0] * 16   # folded to it
        self.fq_n = [0] * 16    # faced our postflop aggression
        self.fq_f = [0] * 16
        self.seen_pf = set()
        self.my_aggr = False
        self.pf_aggr = False
        self.street_seen = -1
        self.nr_pf = 0
        self.tb_n = [0] * 16    # faced exactly one preflop raise
        self.tb_r = [0] * 16    # ... and re-raised
        self.pend = None
        self.pend_jam = False
        self.pend_hand = -5
        self.pend_st = 0
        self.jn = [0] * 16      # our jams faced (inferred)
        self.jc = [0] * 16      # ... called

    def hand_end(self, result):
        try:
            if self.pend and isinstance(result, dict) and self.p['pend'] > 0:
                st = result.get('stacks')
                hn = result.get('hand_no', self.pend_hand)
                if isinstance(st, (list, tuple)) and hn == self.pend_hand:
                    self._settle(dict((i, st[i]) for i in self.pend if i < len(st)))
                    self.pend = None
        except Exception:
            self.pend = None

    def _settle(self, now):
        # opponents who had to respond to our last raise but whose response we never saw
        try:
            for s, chips in self.pend.items():
                if s not in now:
                    continue
                folded = now[s] == chips
                if self.pend_st == 0:
                    self.ftb_n[s] += 1
                    if folded:
                        self.ftb_f[s] += 1
                else:
                    self.fq_n[s] += 1
                    if folded:
                        self.fq_f[s] += 1
                if self.pend_jam:
                    self.jn[s] += 1
                    if not folded:
                        self.jc[s] += 1
        except Exception:
            pass
        self.pend = None

    # ------------------------------------------------------------ stats
    def _nposts(self, obs, hist):
        """number of leading history entries that are blind posts (whatever they are called)."""
        try:
            n = len(obs.stacks)
            bt = obs.button
            alive = [i for i in range(n) if obs.stacks[i] + obs.bets[i] > 0 or obs.in_hand[i]]
            if len(alive) == 2:
                sb = bt
            else:
                sb = (bt + 1) % n
                while sb not in alive:
                    sb = (sb + 1) % n
            bbs = (sb + 1) % n
            while bbs not in alive:
                bbs = (bbs + 1) % n
            bbv = obs.blinds[1]
            k = 0
            for j in range(min(2, len(hist))):
                s, kind, amt = ent(hist[j])
                if kind in ('fold', 'check'):
                    break
                if kind not in ('call', 'raise'):
                    k = j + 1
                    continue
                if s == (sb if j == 0 else bbs) and 0 < amt <= bbv:
                    k = j + 1
                else:
                    break
            return k
        except Exception:
            return 0

    def _scan(self, obs):
        hist = obs.history or []
        if obs.hand_no != self.hand:
            pd = self.pend
            if pd and obs.street == 0 and self.p['pend'] > 0 and obs.hand_no == self.pend_hand + 1:
                self._settle(dict((i, obs.stacks[i] + obs.bets[i]) for i in pd if i < len(obs.stacks)))
            self.pend = None
            self.hand = obs.hand_no
            self.hk = 0
            self.seen_pf = set()
            self.my_aggr = False
            self.pf_aggr = False
            self.street_seen = obs.street
            self.vp_hand = set()
            self.nr_pf = 0
        n = len(obs.stacks)
        if n > 16:
            n = 16
        st = obs.street
        if self.hk == 0 and st == 0:
            self.hk = self._nposts(obs, hist)
        pfe = len(hist)
        if st > 0:
            pfe = self.hk_pf_end(obs, hist) if self.street_seen == 0 else self.hk
        for j in range(self.hk, len(hist)):
            try:
                s, kind, amt = ent(hist[j])
            except Exception:
                continue
            if not isinstance(s, int) or s < 0 or s >= 16:
                continue
            pre = j < pfe
            if s == self.seat:
                if kind == 'raise' and pre:
                    self.nr_pf += 1
                if kind == 'raise':
                    self.my_aggr = True
                    if st == 0:
                        self.pf_aggr = True
                else:
                    self.my_aggr = False
                continue
            if kind not in ('fold', 'check', 'call', 'raise'):
                continue
            if self.pend and s in self.pend:
                del self.pend[s]
            if kind == 'raise' and st == 0 and j < 2:
                try:
                    if amt <= obs.blinds[1]:
                        continue   # a blind post recorded as a raise
                except Exception:
                    pass
            if self.my_aggr and kind != 'check':
                if self.pend_st == 0:
                    self.ftb_n[s] += 1
                    if kind == 'fold':
                        self.ftb_f[s] += 1
                else:
                    self.fq_n[s] += 1
                    if kind == 'fold':
                        self.fq_f[s] += 1
            if pre:
                if self.nr_pf == 1:
                    self.tb_n[s] += 1
                    if kind == 'raise':
                        self.tb_r[s] += 1
                if kind == 'raise':
                    self.nr_pf += 1
                if s not in self.seen_pf:
                    self.seen_pf.add(s)
                    self.npf[s] += 1
                if kind in ('call', 'raise') and s not in self.vp_hand:
                    self.vp_hand.add(s)
                    self.vpip[s] += 1
                    if kind == 'raise':
                        self.pfr[s] += 1
                        try:
                            if obs.stacks[s] == 0 and obs.in_hand[s]:
                                self.shv[s] += 1
                        except Exception:
                            pass
            else:
                self.pact[s] += 1
                if kind == 'raise':
                    self.pagg[s] += 1
        self.hk = len(hist)
        self.street_seen = st

    def hk_pf_end(self, obs, hist):
        # first postflop decision: entries before the positional suffix belong to preflop
        n = len(obs.stacks)
        me = self.seat
        bt = obs.button
        mypos = (me - bt - 1) % n
        j = len(hist) - 1
        last = mypos
        while j >= self.hk:
            s = hist[j][0]
            if not isinstance(s, int):
                break
            p = (s - bt - 1) % n
            if p < last:
                last = p
                j -= 1
            else:
                break
        return j + 1

    def vp(self, s):
        return (self.vpip[s] + 0.28 * 4) / (self.npf[s] + 4.0)

    def pr(self, s):
        return (self.pfr[s] + 0.14 * 4) / (self.npf[s] + 4.0)

    def ag(self, s):
        return (self.pagg[s] + 0.3 * 5) / (self.pact[s] + 5.0)

    def ftb(self, s):
        return (self.ftb_f[s] + 0.45 * 4) / (self.ftb_n[s] + 4.0)

    def ftbp(self, s):
        return (self.fq_f[s] + 0.42 * 4) / (self.fq_n[s] + 4.0)

    def shove_rate(self, s):
        return (self.shv[s] + 0.02 * 4) / (self.npf[s] + 4.0)

    # ------------------------------------------------------------ helpers
    def act(self, obs):
        try:
            a = self._act(obs)
            a = self._legalize(obs, a)
            if a[0] == 'raise':
                me = obs.seat
                self.pend = dict((i, obs.stacks[i]) for i in range(len(obs.stacks))
                                 if i != me and obs.in_hand[i] and obs.stacks[i] > 0)
                self.pend_jam = a[1] >= obs.max_raise
                self.pend_hand = obs.hand_no
                self.pend_st = obs.street
            else:
                self.pend = None
            return a
        except Exception as ex:
            a = None
            Bot.ERRS += 1
            if Bot.LAST_ERR is None:
                import traceback
                Bot.LAST_ERR = traceback.format_exc()
        return self._legalize(obs, a)

    def _legalize(self, obs, a):
        legal = obs.legal
        try:
            if a is not None and a[0] in legal:
                if a[0] == 'raise':
                    amt = int(a[1])
                    lo, hi = obs.min_raise, obs.max_raise
                    if amt < lo:
                        amt = lo
                    if amt > hi:
                        amt = hi
                    if lo <= amt <= hi:
                        return ('raise', amt)
                else:
                    return (a[0], 0)
            if a is not None and a[0] == 'raise' and 'call' in legal:
                return ('call', 0)
        except Exception:
            pass
        if 'check' in legal:
            return ('check', 0)
        if 'fold' in legal:
            return ('fold', 0)
        if 'call' in legal:
            return ('call', 0)
        for x in legal:
            if x == 'raise':
                return ('raise', obs.min_raise)
            return (x, 0)
        return ('fold', 0)

    def _ctx(self, obs):
        n = len(obs.stacks)
        stacks = obs.stacks
        bets = obs.bets
        tot = 0
        alive = 0
        for i in range(n):
            t = stacks[i] + bets[i]
            if t > 0 or obs.in_hand[i]:
                alive += 1
            tot += t
        tot += obs.pot
        return n, alive, tot

    def V(self, s, alive, tot):
        return icm(s, alive, tot)

    def _act(self, obs):
        self._scan(obs)
        if obs.street == 0:
            return self._preflop(obs)
        return self._postflop(obs)

    def _raise(self, obs, amt):
        if 'raise' not in obs.legal:
            return ('call', 0) if 'call' in obs.legal else ('check', 0)
        amt = int(amt)
        if amt >= obs.max_raise * 0.8:
            amt = obs.max_raise
        if amt < obs.min_raise:
            amt = obs.min_raise
        if amt > obs.max_raise:
            amt = obs.max_raise
        return ('raise', amt)

    def _cc(self, obs):
        return ('check', 0) if 'check' in obs.legal else ('call', 0)

    def _fold(self, obs):
        return ('check', 0) if 'check' in obs.legal else ('fold', 0)

    # ------------------------------------------------------------ preflop
    def _preflop(self, obs):
        p = self.p
        n, alive, tot = self._ctx(obs)
        me = obs.seat
        sbv, bb = obs.blinds
        if bb <= 0:
            bb = 1
        bets = obs.bets
        stacks = obs.stacks
        S = stacks[me] + bets[me]
        h = pf_index(obs.hole[0], obs.hole[1])
        hp = PCT[h]
        mx = max(bets)
        potot = obs.pot + sum(bets)
        # raisers this hand (exclude blind posts)
        raisers = []
        limpers = 0
        hist0 = obs.history or []
        for e in hist0[self._nposts(obs, hist0):]:
            try:
                s, kind, amt = ent(e)
                if kind == 'raise' and s != me and amt > bb:
                    raisers.append(s)
                elif kind == 'call' and s != me and not raisers:
                    limpers += 1
            except Exception:
                pass
        if mx <= bb:
            raisers = []
        nraise = len(raisers)
        # players behind (still to act after us this round) and their totals
        behind = []
        i = (me + 1) % n
        while i != me:
            if obs.in_hand[i] and stacks[i] > 0:
                behind.append(i)
            i = (i + 1) % n
        # who can still act after us: in unopened pot all in-hand players with chips except those who already
        # matched? simple: everyone else in hand with chips
        others = [i for i in range(n) if i != me and obs.in_hand[i]]
        eff = 0
        for i in others:
            t = stacks[i] + bets[i]
            if t > eff:
                eff = t
        eff = min(eff, S)
        effbb = eff / float(bb)
        to_call = obs.to_call
        if nraise == 0:
            return self._unopened(obs, h, hp, S, eff, effbb, bb, potot, limpers, alive, tot)
        return self._facing(obs, h, hp, S, eff, effbb, bb, potot, raisers, alive, tot)

    def _behind_order(self, obs):
        """players yet to act after us this preflop round (those with chips), in order."""
        n = len(obs.stacks)
        me = obs.seat
        res = []
        i = (me + 1) % n
        while i != me:
            if obs.in_hand[i] and obs.stacks[i] > 0:
                res.append(i)
            i = (i + 1) % n
        return res

    def _jam_ev(self, obs, h, S, alive, tot, players, bb, my_range):
        """EV (ICM points) of jamming S total vs fold. players: seats that may call."""
        bets = obs.bets
        stacks = obs.stacks
        me = obs.seat
        potot = obs.pot + sum(bets)
        dead = potot - bets[me]
        pf = 1.0
        ev = 0.0
        p = self.p
        for i in players:
            Ti = stacks[i] + bets[i]
            x = min(S, Ti)
            risk = x - bets[i]
            if risk <= 0:
                continue
            # caller's pot odds
            q = risk / float(dead + x + risk)   # caller's required equity: risk / final pot
            if p['cicm'] > 0:
                # caller's own ICM pressure: fold value vs win/lose stacks
                cs = Ti - bets[i]
                vf = icm(cs, alive, tot)
                vwn = icm(cs + dead + x, alive - (1 if Ti >= S else 0), tot)
                vls = icm(Ti - x, alive - (1 if x >= Ti else 0), tot) if Ti - x > 0 else PTS[alive - 1]
                if vwn > vls:
                    qi = (vf - vls) / (vwn - vls)
                    q = q + p['cicm'] * (qi - q)
            q += p['cq']
            w = call_width(my_range, q)
            L = self.vp(i) / 0.28
            if L > 1.0:
                w = w + (1.0 - w) * min(0.9, (L - 1.0) * 0.45)
            elif L < 1.0:
                w *= max(0.5, L)
            if self.jn[i] and p['pend'] > 0:
                w = (self.jc[i] + w * 3.0) / (self.jn[i] + 3.0)
            if w > 1.0:
                w = 1.0
            if w < 0.01:
                w = 0.01
            e = eqr(h, w)
            cover = S >= Ti
            win_s = S + dead - bets[i] + x
            lose_s = S - x
            a2 = alive - 1 if cover else alive
            vw = self.V(win_s, a2, tot)
            vl = self.V(lose_s, alive, tot) if lose_s > 0 else PTS[alive - 1]
            ev += pf * w * (e * vw + (1 - e) * vl)
            pf *= (1.0 - w)
        ev += pf * self.V(S + dead, alive, tot)
        return ev

    def _unopened(self, obs, h, hp, S, eff, effbb, bb, potot, limpers, alive, tot):
        p = self.p
        me = obs.seat
        beh = self._behind_order(obs)
        # players to act after us in this round (in an unopened pot, everybody after us until BB)
        nb = len(beh)
        fold_v = self.V(obs.stacks[me], alive, tot)
        # push/fold zone
        if effbb <= p['jam_bb'] or S <= p['jam_bb'] * bb:
            my_range = {1: 0.45, 2: 0.28, 3: 0.2, 4: 0.15, 5: 0.12}.get(nb, 0.1)
            my_range = min(1.0, my_range * (10.0 / max(effbb, 2.0)) ** 0.7)
            evj = self._jam_ev(obs, h, S, alive, tot, beh, bb, my_range)
            if 'check' in obs.legal:
                # BB option: compare jam with check (take free flop, value ~ fold value + small equity)
                if evj > fold_v + 0.02 and hp < 0.35:
                    return self._raise(obs, obs.max_raise)
                return ('check', 0)
            if evj > fold_v + p['pf_margin'] - p['jam_bias'] * (fold_v - self.V(obs.stacks[me] - bb, alive, tot)):
                return self._raise(obs, obs.max_raise)
            # cheap complete from SB with good odds
            return self._fold(obs)
        # open-raise ranges by number of players behind
        base = {0: 0.5, 1: 0.45, 2: 0.36, 3: 0.27, 4: 0.21, 5: 0.17, 6: 0.15}.get(nb, 0.13)
        if alive == 2 and p['hu_open'] > 0:
            base = p['hu_open']
        ft = 0.45
        if beh:
            ft = sum(self.ftb(i) for i in beh) / len(beh)
            loose = sum(self.vp(i) for i in beh) / len(beh)
        else:
            loose = 0.28
        w = base * p['open_scale'] * (1.0 + p['adapt'] * (ft - 0.45) * 1.2)
        if loose > 0.4:
            w *= 0.8   # loose callers behind: open tighter, value-heavier
        if limpers:
            w = min(w, 0.12 + 0.02 * nb) * 0.8
        if effbb < 25:
            w *= 0.85
        if 'check' in obs.legal:
            # BB facing limps: raise strong, else check
            iso = 0.10 + (0.06 if limpers <= 1 else 0)
            if alive == 2 and p['hu_iso'] > 0:
                iso = p['hu_iso']
            if hp < iso:
                return self._raise(obs, bb * (3 + limpers) + obs.pot)
            return ('check', 0)
        if hp < w:
            size = bb * (2.3 if nb <= 3 else 2.5) + limpers * bb
            if nb == 1:
                size = 3 * bb if alive > 2 else 2.5 * bb
            if effbb < 25 and hp < 0.04:
                size = 2.2 * bb
            return self._raise(obs, size)
        # limp behind / complete with speculative hands when cheap
        if obs.to_call <= bb and limpers >= 1 and effbb > 30 and hp < 0.42:
            if h < 13 or (h < 91 and hp < 0.45):
                return ('call', 0)
        if obs.to_call <= bb // 2 + 1 and nb == 1 and hp < 0.6 and effbb > 20:
            return ('call', 0)
        return self._fold(obs)

    def _range_of_raiser(self, obs, s, nraise, bb):
        stacks = obs.stacks
        bets = obs.bets
        allin = stacks[s] == 0
        r = self.pr(s)
        T = stacks[s] + bets[s]
        if allin:
            depth = T / float(bb)
            # players who were still to act behind the shover (position): count seats after s up to us/BB
            n = len(stacks)
            nbh = 0
            if nraise <= 1:
                bt = obs.button
                ps = (s - bt - 1) % n
                for i in range(n):
                    if i != s and (stacks[i] + bets[i]) > 0 and (i - bt - 1) % n > ps:
                        nbh += 1
                pos = {0: 1.6, 1: 1.6, 2: 1.25, 3: 1.0, 4: 0.85}.get(nbh, 0.7)
            else:
                pos = 0.8
            prior = 0.03 if depth > 30 else (0.06 if depth > 20 else (0.11 if depth > 12 else (0.2 if depth > 7 else 0.35)))
            prior = min(0.8, prior * pos)
            k = 6.0
            w = (self.shv[s] + prior * k) / (self.npf[s] + k)
            # frequency -> range width (situational shoves are wider than the raw frequency)
            w = w * self.p['shove_mult']
            if depth <= 12:
                w = max(w, prior * 0.8)
            if nraise >= 2:
                w *= 0.7
            w = max(w, 0.02)
        else:
            if nraise <= 1:
                w = r * 1.15
                if self.p['pos_r'] > 0:
                    n = len(stacks)
                    bt = obs.button
                    ps = (s - bt - 1) % n
                    nbh = 0
                    for i in range(n):
                        if i != s and (stacks[i] + bets[i]) > 0 and (i - bt - 1) % n > ps:
                            nbh += 1
                    alive = sum(1 for i in range(n) if stacks[i] + bets[i] > 0)
                    if alive == 2:
                        f = 3.0
                    else:
                        f = {0: 2.2, 1: 2.2, 2: 1.6, 3: 1.25, 4: 1.0}.get(nbh, 0.8)
                    w = w * (1.0 + self.p['pos_r'] * (f - 1.0))
            elif nraise == 2:
                w = r * 0.4
                if self.p['tb3'] > 0:
                    w3 = (self.tb_r[s] + 0.07 * 5) / (self.tb_n[s] + 5.0) * 1.2
                    w = w + self.p['tb3'] * (w3 - w)
            else:
                w = r * 0.18
            w = max(w, 0.025)
        if self.vp(s) > 0.55 and self.npf[s] >= 6:
            w = max(w, 0.5)
        return min(1.0, w)

    def _facing(self, obs, h, hp, S, eff, effbb, bb, potot, raisers, alive, tot):
        p = self.p
        me = obs.seat
        stacks = obs.stacks
        bets = obs.bets
        nraise = len(raisers)
        r = raisers[-1]
        wr = self._range_of_raiser(obs, r, nraise, bb)
        # multiple distinct aggressors / callers -> stronger
        callers = sum(1 for i in range(len(stacks)) if i != me and i != r and obs.in_hand[i] and bets[i] >= max(bets) and bets[i] > 0)
        e = eqr(h, wr)
        if callers:
            e = e ** (1.0 + 0.6 * callers)
        to_call = obs.to_call
        fold_v = self.V(stacks[me], alive, tot)
        Tr = stacks[r] + bets[r]
        beh = [i for i in self._behind_order(obs) if i != r]
        nbeh = len([i for i in beh if bets[i] < max(bets)])
        commit = to_call >= 0.4 * S or stacks[me] - to_call < 6 * bb
        if commit or stacks[r] == 0:
            # all-in style decision: call (or jam) with ICM
            x = min(S, Tr)
            win_s = S + (potot - bets[me] - bets[r]) + x
            excess = 0
            for i in range(len(stacks)):
                if i != me and bets[i] > S:
                    excess += bets[i] - S
            win_s = S - x + (potot + to_call - excess) if False else S + (potot - bets[me]) - excess
            lose_s = S - x
            cover = S >= Tr
            vw = self.V(win_s, alive - 1 if cover and stacks[r] == 0 else alive, tot)
            vl = self.V(lose_s, alive, tot) if lose_s > 0 else PTS[alive - 1]
            req = (fold_v - vl) / (vw - vl) if vw > vl else 1.0
            req += 0.015 * nbeh
            if e >= req + p['pf_margin']:
                if 'raise' in obs.legal and stacks[r] > 0:
                    return self._raise(obs, obs.max_raise)
                return ('call', 0)
            # re-jam with fold equity when raiser not all-in and we are short
            if 'raise' in obs.legal and stacks[r] > 0 and S <= 25 * bb:
                ev = self._rejam_ev(obs, h, S, alive, tot, r, wr, bb)
                if ev > fold_v + 0.03:
                    return self._raise(obs, obs.max_raise)
            return self._fold(obs)
        # deep: 3bet / call / fold
        if effbb <= 25 and 'raise' in obs.legal:
            ev = self._rejam_ev(obs, h, S, alive, tot, r, wr, bb)
            if ev > fold_v + 0.02 and (e > 0.5 or nraise == 1):
                return self._raise(obs, obs.max_raise)
        pot_after = potot + to_call
        odds = to_call / float(pot_after)
        # value raise
        val_th = 0.60 if nraise == 1 else 0.64
        if e >= val_th and 'raise' in obs.legal:
            size = max(bets) * (3.0 if nraise == 1 else 2.4) + callers * max(bets)
            if size > 0.4 * S:
                size = obs.max_raise
            return self._raise(obs, size)
        # light 3bet bluff vs frequent openers who fold
        if nraise == 1 and 'raise' in obs.legal and 0.06 < hp < 0.2 and callers == 0 and effbb > 35:
            if self.pr(r) > 0.22 and self.rng.random() < 0.3 * p['c3bet'] * self.ftb(r) / 0.45:
                return self._raise(obs, max(bets) * 3.2)
        implied = 0.0
        if effbb > 40 and to_call < 0.08 * S:
            if h < 13:
                implied = 0.08
            elif h < 91 and hp < 0.4:
                implied = 0.04
        if 'check' in obs.legal:
            return ('check', 0)
        if e + implied >= odds + p['call_margin'] + 0.02 * nbeh and to_call <= 0.25 * S:
            # don't flat with junk vs big raises
            if e >= 0.36 or implied > 0:
                return ('call', 0)
        return self._fold(obs)

    def _rejam_ev(self, obs, h, S, alive, tot, r, wr, bb):
        stacks = obs.stacks
        bets = obs.bets
        me = obs.seat
        potot = obs.pot + sum(bets)
        Tr = stacks[r] + bets[r]
        x = min(S, Tr)
        dead = potot - bets[me]
        risk = x - bets[r]
        q = risk / float(dead + x + risk) + self.p['cq']
        wc = call_width(0.15, q)   # their calling range width as a fraction of all hands
        wc = min(wc, wr)
        if self.vp(r) > 0.5:
            wc = max(wc, wr * 0.8)
        pc = wc / wr if wr > 0 else 1.0
        e = eqr(h, max(wc, 0.02))
        cover = S >= Tr
        win_s = S + dead - bets[r] + x
        lose_s = S - x
        vw = self.V(win_s, alive - 1 if cover else alive, tot)
        vl = self.V(lose_s, alive, tot) if lose_s > 0 else PTS[alive - 1]
        vf = self.V(S + dead, alive, tot)
        return (1 - pc) * vf + pc * (e * vw + (1 - e) * vl)

    def _stackoff_req(self, obs, alive, tot, opps):
        """ICM equity needed to get all our chips in now vs the biggest opponent stack in the hand."""
        me = obs.seat
        S = obs.stacks[me]
        mine = S + obs.bets[me]
        big = 0
        for i in opps:
            t = obs.stacks[i] + obs.bets[i]
            if t > big:
                big = t
        x = min(mine, big)              # matched this street
        potot = obs.pot + sum(obs.bets)
        # pot if all-in matched: previous pot + others' current bets (capped) + our x + their x
        others_in = 0
        for i in range(len(obs.stacks)):
            if i != me:
                others_in += min(obs.bets[i], x)
        topp = None
        for i in opps:
            if obs.stacks[i] + obs.bets[i] == big:
                topp = i
        win_s = (mine - x) + obs.pot + x + x + (others_in - (min(obs.bets[topp], x) if topp is not None else 0))
        lose_s = mine - x
        vf = self.V(S, alive, tot)
        vw = self.V(win_s, alive - 1 if mine >= big else alive, tot)
        vl = self.V(lose_s, alive, tot) if lose_s > 0 else PTS[alive - 1]
        if vw <= vl:
            return 1.0
        return (vf - vl) / (vw - vl)

    # ------------------------------------------------------------ postflop
    def _postflop(self, obs):
        p = self.p
        n, alive, tot = self._ctx(obs)
        me = obs.seat
        stacks = obs.stacks
        bets = obs.bets
        bb = obs.blinds[1] or 1
        key, made, draw = classify(obs.hole, obs.board)
        e0, e1, e2, e3 = post_eq(key)
        opps = [i for i in range(n) if i != me and obs.in_hand[i]]
        nopp = len(opps)
        if nopp == 0:
            return self._cc(obs)
        potot = obs.pot + sum(bets)
        to_call = obs.to_call
        S = stacks[me]
        mx = max(bets)
        st = obs.street
        mexp = 1.0 + 0.75 * (nopp - 1)
        if to_call == 0:
            # range when checked to / first to act: continuing range
            eq_now = (0.45 * e0 + 0.55 * e1) ** mexp
            # equity vs calling range given their call tendencies
            ft = 1.0
            for i in opps:
                ft *= self.ftbp(i)
            stn = 1.0 - sum(self.ftbp(i) for i in opps) / nopp   # avg call rate
            if stn > 0.7:
                evc = e0 * 0.6 + e1 * 0.4
            elif stn > 0.5:
                evc = e1
            else:
                evc = 0.5 * e1 + 0.5 * e2
            evc = evc ** mexp
            spr = S / float(potot) if potot > 0 else 10
            if p['slow'] > 0 and evc > 0.86 and st < 3 and nopp == 1 and spr > 1.5 and self.ag(opps[0]) > 0.33:
                if self.rng.random() < p['slow']:
                    return ('check', 0)
            if evc >= p['vbet'] and 'raise' in obs.legal:
                if evc < 0.68:
                    frac = 0.45 if stn < 0.6 else 0.6
                    jam_spr = 0.6
                elif evc < 0.82:
                    frac = 0.66 if stn < 0.6 else 0.8
                    jam_spr = 1.0
                else:
                    frac = 0.8 if stn < 0.6 else 1.0
                    jam_spr = 1.5
                amt = int(potot * frac * (0.9 + 0.2 * self.rng.random()))
                if spr < jam_spr:
                    amt = obs.max_raise
                    if p['jg'] > 0 and spr > 0.45:
                        ecall = (0.5 * e2 + 0.5 * e3) ** mexp
                        if ecall < self._stackoff_req(obs, alive, tot, opps) and evc < 0.8:
                            amt = int(potot * 0.4)
                elif amt > 0.6 * S and evc < 0.8:
                    amt = int(0.5 * S)
                if p['pc'] > 0 and made < 11 and spr >= jam_spr and amt > 0.35 * S:
                    amt = int(0.35 * S)   # pot control with one-pair hands
                if amt < bb:
                    amt = bb
                if amt >= obs.max_raise * 0.8 and evc < 0.8 and spr >= jam_spr:
                    amt = int(obs.max_raise * 0.6)
                    if amt < obs.min_raise:
                        amt = obs.min_raise
                    return ('raise', amt) if amt <= obs.max_raise else ('check', 0)
                return self._raise(obs, amt)
            # bluff / semi-bluff
            if 'raise' in obs.legal and nopp <= 2:
                bf = (ft - 0.3) * 1.6 * p['bluff']
                if draw >= 2 and st < 3:
                    bf += 0.25
                if self.pf_aggr and st == 1:
                    bf += 0.15
                if st == 3 and e1 > 0.35:
                    bf = 0  # has showdown value: check
                if nopp == 2:
                    bf *= 0.5
                if bf > 0 and self.rng.random() < min(0.7, bf):
                    if p['bsize'] > 0:
                        amt = int(potot * (0.45 + 0.35 * self.rng.random()))
                    else:
                        amt = int(potot * (0.5 if st < 3 else 0.6))
                    if amt < bb:
                        amt = bb
                    if amt > 0.45 * S and draw < 2:
                        return ('check', 0)
                    return self._raise(obs, amt)
            return ('check', 0)
        # facing a bet
        aggs = [i for i in opps if bets[i] >= mx and bets[i] > 0]
        a = aggs[0] if aggs else opps[0]
        agf = self.ag(a)
        beta = agf * 0.9 * p['adapt'] + 0.3 * (1 - p['adapt'])
        if beta < 0.12:
            beta = 0.12
        if beta > 0.7:
            beta = 0.7
        bet_frac = (mx - bets[me]) / float(max(1, potot - (mx - bets[me])))
        raised_us = bets[me] > 0
        if raised_us:
            beta *= 0.6
            val = e3
        elif bet_frac > 0.9:
            val = 0.4 * e2 + 0.6 * e3
        else:
            val = 0.75 * e2 + 0.25 * e3
        ef = beta * (0.5 * e0 + 0.5 * e1) + (1 - beta) * val
        if p['fr'] > 0:
            fb = agf * 0.75
            if raised_us:
                fb *= 0.5
            elif bet_frac > 0.9:
                fb *= 0.8
            ef2 = range_eq(st, fb, e0, e1, e2, e3)
            ef2 = 0.1 * e0 + 0.9 * ef2
            ef = ef + p['fr'] * (ef2 - ef)
        others = nopp - 1
        if others > 0:
            ef = ef ** (1.0 + 0.6 * others)
        odds = to_call / float(potot + to_call)
        implied = 0.0
        if st < 3 and draw >= 2 and S > 4 * potot:
            implied = 0.04 if draw == 2 or draw == 3 else 0.06
        big = to_call >= 0.35 * S or S - to_call < 3 * bb
        if big:
            x = to_call
            excess = 0
            for i in range(n):
                if i != me and bets[i] > bets[me] + S:
                    excess += bets[i] - bets[me] - S
            win_s = S + potot - excess
            lose_s = S - to_call
            fold_v = self.V(S, alive, tot)
            cover = all(stacks[i] + bets[i] <= S + bets[me] for i in aggs) and stacks[a] == 0
            vw = self.V(win_s, alive - 1 if cover else alive, tot)
            vl = self.V(lose_s, alive, tot) if lose_s > 0 else PTS[alive - 1]
            req = (fold_v - vl) / (vw - vl) if vw > vl else 1.0
            req = req * p['icm_on'] + odds * (1 - p['icm_on'])
        else:
            req = odds
            if p['icm_post'] > 0:
                fold_v = self.V(S, alive, tot)
                vw = self.V(S + potot, alive, tot)
                vl = self.V(S - to_call, alive, tot)
                if vw > vl:
                    ri = (fold_v - vl) / (vw - vl)
                    req = odds + p['icm_post'] * (ri - odds)
        # value raise
        rth = p['raise_th']
        if p['pc'] > 0:
            if st == 3:
                rth = max(rth, 0.8)
                if made < 11:
                    rth = 0.9
            elif made < 9 and draw < 3:
                rth = max(rth, 0.8)
        if ef >= rth and 'raise' in obs.legal and not (raised_us and ef < 0.85):
            size = mx * 2.8 + (potot - mx) * 0.3
            if size > 0.45 * (S + bets[me]):
                size = obs.max_raise
            if p['jg'] > 0 and size >= obs.max_raise * 0.8 and S > 1.2 * potot:
                ecall = (0.35 * ef + 0.65 * e3) ** (1.0 + 0.6 * (nopp - 1))
                if ecall < self._stackoff_req(obs, alive, tot, opps) + 0.02:
                    if ef + implied >= req + p['call_margin']:
                        return ('call', 0)
                    return self._fold(obs)
            return self._raise(obs, size)
        # semi-bluff raise
        if 'raise' in obs.legal and st == 1 and draw == 4 and nopp == 1 and not raised_us and S > 2 * potot:
            if self.rng.random() < 0.35 * p['bluff']:
                return self._raise(obs, mx * 3)
        if ef + implied >= req + p['call_margin']:
            return ('call', 0)
        return self._fold(obs)
